def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'

    # Endgame: always defect on the last round
    if n >= 99:
        return 'D'

    opp_d = sum(1 for _, o in history if o == 'D')

    if opp_d == 0:
        # Opponent has never defected. Exploit by defecting periodically.
        if n >= 6 and n % 6 == 0:
            return 'D'
        return 'C'
    else:
        # Opponent has defected at least once. Use forgiving TFT.
        last_me, last_opp = history[-1]
        if last_opp == 'D':
            # Forgive if opponent hasn't defected too much overall.
            if opp_d <= n * 0.3:
                return 'C'
            return 'D'
        else:
            return 'C'
